return $build(array(
 'key'=>'english-sd5-fase-c','grade'=>'sd_5','category'=>'bahasa-inggris','slug'=>'bahasa-inggris-kelas-5-main-ideas-experiences-and-plans',
 'title'=>'Bahasa Inggris Kelas 5 — Main Ideas, Experiences, and Plans',
 'summary'=>'Delapan bab awal Fase C: gagasan utama/rincian, alur menyimak, was/were, pengalaman lampau, rencana, jumlah, pendapat beralasan dan teks pesan/prosedur. Bacaan original dengan penjelasan Indonesia serta tugas produksi kalimat pendek.',
 'objectives'=>"Memahami alur dan gagasan utama teks pendek sehari-hari.\nMembedakan informasi rinci dari asumsi.\nMenceritakan pengalaman/rencana rekaan dengan pola dasar.\nMenulis pesan dan tanggapan yang sesuai konteks.",
 'prerequisites'=>'Dasar FaseB kelas3–4: pertanyaan, simple present, present continuous dan deskripsi. Pendamping membantu menyimak/berbicara; belum ada audio otomatis. Tokoh, tempat, jadwal dan pengalaman dapat rekaan.',
